#include <vulkan/vulkan.h>
#include <stdio.h>
#include <stdlib.h>
#define VK(call) do { VkResult r=(call); if(r) { fprintf(stderr,"%s: %d\n",#call,r); return 1; } } while(0)
int main(int argc,char **argv) {
 if(argc<3) return 2;
 VkApplicationInfo app={.sType=VK_STRUCTURE_TYPE_APPLICATION_INFO,.pApplicationName="coverage-probe",.apiVersion=VK_API_VERSION_1_3};
 VkInstanceCreateInfo ic={.sType=VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO,.pApplicationInfo=&app};VkInstance instance;VK(vkCreateInstance(&ic,0,&instance));
 uint32_t n=1;VkPhysicalDevice physical;VK(vkEnumeratePhysicalDevices(instance,&n,&physical));
 uint32_t qn=0;vkGetPhysicalDeviceQueueFamilyProperties(physical,&qn,0);VkQueueFamilyProperties *qs=calloc(qn,sizeof(*qs));vkGetPhysicalDeviceQueueFamilyProperties(physical,&qn,qs);
 uint32_t queue=0;while(!(qs[queue].queueFlags&VK_QUEUE_COMPUTE_BIT))queue++;free(qs);
 float priority=1;VkDeviceQueueCreateInfo qc={.sType=VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO,.queueFamilyIndex=queue,.queueCount=1,.pQueuePriorities=&priority};
 VkPhysicalDeviceVulkan13Features features={.sType=VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_VULKAN_1_3_FEATURES,.shaderZeroInitializeWorkgroupMemory=VK_TRUE};
 VkDeviceCreateInfo dc={.sType=VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO,.pNext=&features,.queueCreateInfoCount=1,.pQueueCreateInfos=&qc};VkDevice device;VK(vkCreateDevice(physical,&dc,0,&device));
 FILE *f=fopen(argv[1],"rb");if(!f)return 3;fseek(f,0,SEEK_END);size_t size=ftell(f);rewind(f);void *code=malloc(size);if(fread(code,1,size,f)!=size)return 4;fclose(f);
 VkShaderModuleCreateInfo sc={.sType=VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO,.codeSize=size,.pCode=code};VkShaderModule shader;VK(vkCreateShaderModule(device,&sc,0,&shader));free(code);
 VkDescriptorSetLayoutBinding bindings[9]={0};for(int i=0;i<9;i++) bindings[i]=(VkDescriptorSetLayoutBinding){.binding=i,.descriptorType=i?VK_DESCRIPTOR_TYPE_STORAGE_BUFFER:VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER_DYNAMIC,.descriptorCount=1,.stageFlags=VK_SHADER_STAGE_COMPUTE_BIT};
 VkDescriptorSetLayoutCreateInfo bc={.sType=VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO,.bindingCount=9,.pBindings=bindings};VkDescriptorSetLayout layout;VK(vkCreateDescriptorSetLayout(device,&bc,0,&layout));
 VkPipelineLayoutCreateInfo lc={.sType=VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO,.setLayoutCount=1,.pSetLayouts=&layout};VkPipelineLayout pipeline_layout;VK(vkCreatePipelineLayout(device,&lc,0,&pipeline_layout));
 for(int i=2;i<argc;i++) {
  fprintf(stderr,"compiling %s\n",argv[i]);fflush(stderr);
  VkComputePipelineCreateInfo pc={.sType=VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO,.layout=pipeline_layout,.stage={.sType=VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO,.stage=VK_SHADER_STAGE_COMPUTE_BIT,.module=shader,.pName=argv[i]}};
  VkPipeline pipeline;VK(vkCreateComputePipelines(device,VK_NULL_HANDLE,1,&pc,0,&pipeline));vkDestroyPipeline(device,pipeline,0);fprintf(stderr,"compiled %s\n",argv[i]);
 }
 vkDestroyPipelineLayout(device,pipeline_layout,0);vkDestroyDescriptorSetLayout(device,layout,0);vkDestroyShaderModule(device,shader,0);vkDestroyDevice(device,0);vkDestroyInstance(instance,0);return 0;
}
